{
  "timeline": [
    {
      "date": "1930-08-30",
      "headline": "Birth",
      "text": "Warren Edward Buffett was born in Omaha, Nebraska, United States."
    },
    {
      "date": "1941",
      "headline": "First Stock Purchase",
      "text": "At the age of 11, Warren Buffett made his first stock purchase, buying shares of Cities Service Preferred for himself and his sister."
    },
    {
      "date": "1947",
      "headline": "Enters University of Pennsylvania",
      "text": "Buffett enrolled at the Wharton School of the University of Pennsylvania to study business."
    },
    {
      "date": "1950",
      "headline": "Transfers to University of Nebraska",
      "text": "Buffett transferred to the University of Nebraska, where he graduated with a Bachelor of Science in Business Administration."
    },
    {
      "date": "1951",
      "headline": "Graduates from Columbia University",
      "text": "Buffett earned a Master of Science in Economics from Columbia University, studying under Benjamin Graham."
    },
    {
      "date": "1956",
      "headline": "Founds Buffett Partnership Ltd.",
      "text": "Warren Buffett founded Buffett Partnership Ltd., an investment partnership based in Omaha."
    },
    {
      "date": "1965",
      "headline": "Takes Control of Berkshire Hathaway",
      "text": "Buffett took control of Berkshire Hathaway, a textile manufacturing firm, which he later transformed into a diversified holding company."
    },
    {
      "date": "1970",
      "headline": "Becomes Chairman and CEO of Berkshire Hathaway",
      "text": "Warren Buffett became the Chairman and CEO of Berkshire Hathaway, a position he holds to this day."
    },
    {
      "date": "2006",
      "headline": "Announces Philanthropic Pledge",
      "text": "Buffett announced his intention to give away 85% of his Berkshire Hathaway stock to philanthropic foundations, primarily the Bill & Melinda Gates Foundation."
    },
    {
      "date": "2010",
      "headline": "Launches The Giving Pledge",
      "text": "Alongside Bill and Melinda Gates, Buffett launched The Giving Pledge, encouraging billionaires to commit to giving away at least half of their wealth to charitable causes."
    }
  ]
}

