{
  "timeline": [
    {
      "date": "1867-11-07",
      "headline": "Birth of Marie Curie",
      "text": "Marie Curie was born as Maria Salomea Skłodowska in Warsaw, Poland, which was then part of the Russian Empire."
    },
    {
      "date": "1891",
      "headline": "Moved to Paris",
      "text": "Marie Curie moved to Paris to continue her studies at the University of Paris (Sorbonne), where she earned higher degrees and conducted her subsequent scientific work."
    },
    {
      "date": "1895-07-26",
      "headline": "Marriage to Pierre Curie",
      "text": "Marie Skłodowska married Pierre Curie, a French physicist, marking the beginning of a significant scientific partnership."
    },
    {
      "date": "1898-07",
      "headline": "Discovery of Polonium",
      "text": "Marie and Pierre Curie announced the discovery of a new element, polonium, named after Marie's native Poland."
    },
    {
      "date": "1898-12-26",
      "headline": "Discovery of Radium",
      "text": "The Curies announced the discovery of another element, radium, which was highly radioactive."
    },
    {
      "date": "1903",
      "headline": "Nobel Prize in Physics",
      "text": "Marie Curie, along with Pierre Curie and Henri Becquerel, was awarded the Nobel Prize in Physics for their joint research on radiation phenomena."
    },
    {
      "date": "1906-04-19",
      "headline": "Death of Pierre Curie",
      "text": "Pierre Curie died in a street accident in Paris, leaving Marie to continue their work alone."
    },
    {
      "date": "1906",
      "headline": "First Female Professor at the University of Paris",
      "text": "Marie Curie became the first woman to become a professor at the University of Paris, taking over Pierre's teaching position."
    },
    {
      "date": "1911",
      "headline": "Nobel Prize in Chemistry",
      "text": "Marie Curie was awarded the Nobel Prize in Chemistry for her services to the advancement of chemistry by the discovery of the elements radium and polonium, by the isolation of radium and the study of the nature and compounds of this remarkable element."
    },
    {
      "date": "1934-07-04",
      "headline": "Death of Marie Curie",
      "text": "Marie Curie died of aplastic anemia, believed to have been caused by prolonged exposure to radiation, at the Sancellemoz Sanatorium in Passy, France."
    }
  ]
}

