    {
      "date": "-1000",
      "headline": "Early Settlements",
      "text": "The Nok culture, one of the earliest known civilizations in Nigeria, began around 1000 BCE. They were known for their advanced terracotta sculptures."
    },
    {
      "date": "1100",
      "headline": "Rise of Hausa City-States",
      "text": "By the 11th century, the Hausa city-states began to emerge in northern Nigeria, becoming important centers of trade and culture."
    },
    {
      "date": "1400",
      "headline": "Yoruba Kingdoms",
      "text": "The Yoruba kingdoms, including the Oyo Empire, began to rise in southwestern Nigeria, known for their complex political structures and artistic achievements."
    },
    {
      "date": "1472",
      "headline": "Portuguese Contact",
      "text": "Portuguese explorers reached the Nigerian coast, initiating European contact and trade, particularly in slaves."
    },
    {
      "date": "1804",
      "headline": "Fulani Jihad",
      "text": "The Fulani Jihad, led by Usman dan Fodio, began in 1804, leading to the establishment of the Sokoto Caliphate in northern Nigeria."
    },
    {
      "date": "1861",
      "headline": "British Annexation of Lagos",
      "text": "Lagos was annexed by the British in 1861, marking the beginning of formal colonial rule in Nigeria."
    },
    {
      "date": "1914",
      "headline": "Amalgamation of Nigeria",
      "text": "The Northern and Southern protectorates were amalgamated into the Colony and Protectorate of Nigeria by the British in 1914."
    },
    {
      "date": "1960-10-01",
      "headline": "Independence",
      "text": "Nigeria gained independence from the United Kingdom on October 1, 1960, becoming a sovereign nation."
    },
    {
      "date": "1963-10-01",
      "headline": "Republic Declared",
      "text": "Nigeria became a republic on October 1, 1963, with Nnamdi Azikiwe as its first President."
    },
    {
      "date": "1967-05-30",
      "headline": "Biafran War",
      "text": "The Eastern Region declared independence as the Republic of Biafra on May 30, 1967, leading to the Nigerian Civil War."
    },
    {
      "date": "1970-01-15",
      "headline": "End of Biafran War",
      "text": "The Nigerian Civil War ended on January 15, 1970, with the reintegration of Biafra into Nigeria."
    },
    {
      "date": "1979",
      "headline": "Second Republic",
      "text": "Nigeria transitioned to civilian rule in 1979, marking the beginning of the Second Republic."
    },
    {
      "date": "1983",
      "headline": "Military Coup",
      "text": "A military coup in 1983 led by Major General Muhammadu Buhari ended the Second Republic."
    },
    {
      "date": "1999-05-29",
      "headline": "Return to Democracy",
      "text": "Nigeria returned to civilian rule on May 29, 1999, with Olusegun Obasanjo as President, marking the beginning of the Fourth Republic."
    }
  ]
}

