{
  "timeline": [
    {
      "date": "-03100",
      "headline": "Unification of Upper and Lower Egypt",
      "text": "The unification of Upper and Lower Egypt is traditionally attributed to King Narmer (also known as Menes), marking the beginning of the Early Dynastic Period."
    },
    {
      "date": "-02650",
      "headline": "Construction of the Step Pyramid",
      "text": "The Step Pyramid of Djoser, designed by the architect Imhotep, is constructed during the Third Dynasty, marking a significant advancement in Egyptian architecture."
    },
    {
      "date": "-02570",
      "headline": "Reign of Sneferu",
      "text": "Sneferu, the first king of the Fourth Dynasty, is known for building at least three pyramids, including the Bent Pyramid and the Red Pyramid, which are considered architectural milestones."
    },
    {
      "date": "-02560",
      "headline": "Construction of the Great Pyramid of Giza",
      "text": "The Great Pyramid of Giza is constructed during the reign of Pharaoh Khufu (Cheops), becoming one of the Seven Wonders of the Ancient World."
    },
    {
      "date": "-01470",
      "headline": "Reign of Hatshepsut",
      "text": "Hatshepsut becomes one of the most successful female pharaohs, known for her extensive building projects and trade expeditions, including the famous expedition to Punt."
    },
    {
      "date": "-01350",
      "headline": "Reign of Akhenaten",
      "text": "Pharaoh Akhenaten introduces a monotheistic worship of Aten, the sun disk, and moves the capital to Akhetaten (modern-day Amarna), marking a significant religious shift."
    },
    {
      "date": "-01275",
      "headline": "Battle of Kadesh",
      "text": "Ramses II leads Egyptian forces in the Battle of Kadesh against the Hittites, one of the largest chariot battles ever fought, resulting in the first known peace treaty."
    },
    {
      "date": "-00664",
      "headline": "Assyrian Conquest",
      "text": "The Assyrian Empire, under Ashurbanipal, conquers Egypt, marking the end of the Kushite (25th) Dynasty and the beginning of the Assyrian domination."
    },
    {
      "date": "-00332",
      "headline": "Conquest by Alexander the Great",
      "text": "Alexander the Great conquers Egypt, ending Persian rule and beginning the Hellenistic period under the Ptolemaic Dynasty."
    },
    {
      "date": "-00305",
      "headline": "Ptolemaic Dynasty Begins",
      "text": "Ptolemy I Soter, a general under Alexander the Great, declares himself Pharaoh of Egypt, establishing the Ptolemaic Dynasty."
    },
    {
      "date": "-00030",
      "headline": "Death of Cleopatra VII",
      "text": "Cleopatra VII, the last active ruler of the Ptolemaic Kingdom of Egypt, dies, marking the end of the Hellenistic period and the beginning of Roman control."
    },
    {
      "date": "00641",
      "headline": "Islamic Conquest of Egypt",
      "text": "Amr ibn al-As leads the Muslim conquest of Egypt, bringing the region under the control of the Rashidun Caliphate."
    },
    {
      "date": "1517",
      "headline": "Ottoman Conquest",
      "text": "The Ottoman Empire conquers Egypt, incorporating it as a province and ending the Mamluk Sultanate's rule."
    },
    {
      "date": "1798",
      "headline": "Napoleon's Campaign in Egypt",
      "text": "Napoleon Bonaparte leads a French campaign in Egypt, marking the beginning of modern European interest and influence in the region."
    },
    {
      "date": "1882",
      "headline": "British Occupation",
      "text": "The British Empire occupies Egypt, establishing control over the Suez Canal and marking the beginning of British colonial influence."
    },
    {
      "date": "1922",
      "headline": "Egyptian Independence",
      "text": "Egypt gains nominal independence from the United Kingdom, becoming a sovereign state with Fuad I as king."
    },
    {
      "date": "1952",
      "headline": "Egyptian Revolution",
      "text": "The Egyptian Revolution led by the Free Officers Movement results in the abdication of King Farouk and the establishment of a republic."
    },
    {
      "date": "1956",
      "headline": "Suez Crisis",
      "text": "Egypt nationalizes the Suez Canal, leading to a military intervention by Israel, the United Kingdom, and France, and a subsequent international crisis."
    },
    {
      "date": "1979",
      "headline": "Egypt-Israel Peace Treaty",
      "text": "Egypt becomes the first Arab country to sign a peace treaty with Israel, following the Camp David Accords, leading to Egypt's temporary suspension from the Arab League."
    },
    {
      "date": "2011",
      "headline": "Egyptian Revolution",
      "text": "Mass protests lead to the resignation of President Hosni Mubarak, marking a significant moment in the Arab Spring and leading to political upheaval."
    }
  ]
}

