      "date": "1795",
      "headline": "Annexation by France",
      "text": "Luxembourg is annexed by France during the French Revolutionary Wars and becomes part of the département of Forêts."
    },
    {
      "date": "1815",
      "headline": "Congress of Vienna",
      "text": "Luxembourg is elevated to a Grand Duchy and placed under the personal union with the King of the Netherlands, while also becoming a member of the German Confederation."
    },
    {
      "date": "1839",
      "headline": "Treaty of London",
      "text": "The Treaty of London partitions Luxembourg, with the western part becoming Belgian Luxembourg and the eastern part remaining the Grand Duchy of Luxembourg."
    },
    {
      "date": "1867",
      "headline": "Second Treaty of London",
      "text": "Luxembourg's independence and neutrality are reaffirmed, and the fortress of Luxembourg City is dismantled."
    },
    {
      "date": "1890",
      "headline": "End of Personal Union with the Netherlands",
      "text": "With the death of King William III of the Netherlands, the personal union ends, and the House of Nassau-Weilburg takes over the Luxembourg throne."
    },
    {
      "date": "1914-1918",
      "headline": "World War I",
      "text": "Luxembourg is occupied by Germany during World War I, despite its neutral status."
    },
    {
      "date": "1940-1944",
      "headline": "World War II Occupation",
      "text": "Luxembourg is occupied by Nazi Germany during World War II, and the government goes into exile."
    },
    {
