{
  "timeline": [
    {
      "date": "-0500",
      "headline": "Origin in the Indian Subcontinent",
      "text": "Linguistic and genetic evidence suggests that the Romani people originated in the Indian subcontinent, particularly in the region of Rajasthan."
    },
    {
      "date": "0500-1100",
      "headline": "First Wave of Migration",
      "text": "The first wave of westward migration of the Romani people is believed to have occurred sometime between the 5th and 11th centuries."
    },
    {
      "date": "1300-1400",
      "headline": "Arrival in Europe",
      "text": "The Romani people are thought to have arrived in Europe around the 13th to 14th centuries, marking the beginning of their widespread presence across the continent."
    },
    {
      "date": "1417",
      "headline": "First Recorded Arrival in Germany",
      "text": "The Romani people were first recorded in Germany in 1417, marking one of the earliest documented presences in Western Europe."
    },
    {
      "date": "1425",
      "headline": "Arrival in France",
      "text": "The Romani people were recorded in France in 1425, continuing their spread across Europe."
    },
    {
      "date": "1500",
      "headline": "Persecution Begins",
      "text": "By the 16th century, the Romani people began facing widespread persecution, including expulsion and forced assimilation, across various European countries."
    },
    {
      "date": "1530",
      "headline": "Egyptians Act 1530",
      "text": "The Egyptians Act 1530 was passed in England, ordering the expulsion of the Romani people, referred to as 'Egyptians', from the country."
    },
    {
      "date": "1554",
      "headline": "Egyptians Act 1554",
      "text": "A subsequent act in England, the Egyptians Act 1554, imposed penalties on Romani people for remaining in the country and on those who sheltered them."
    },
    {
      "date": "1710",
      "headline": "Deportation from France",
      "text": "In 1710, France began the deportation of Romani people to its overseas colonies as part of its efforts to remove them from the country."
    },
    {
      "date": "1783",
      "headline": "Maria Theresa's Reforms",
      "text": "Empress Maria Theresa of Austria implemented reforms aimed at assimilating the Romani people, including banning their language and traditional dress."
    },
    {
      "date": "1936",
      "headline": "Nazi Persecution",
      "text": "The Romani people were targeted by the Nazi regime, leading to the Porajmos, the Romani Holocaust, during which hundreds of thousands were killed."
    },
    {
      "date": "1971",
      "headline": "First World Romani Congress",
      "text": "The first World Romani Congress was held in London in 1971, marking a significant step in the international recognition and organization of the Romani people."
    },
    {
      "date": "1990",
      "headline": "International Romani Union",
      "text": "The International Romani Union was officially recognized by the United Nations in 1990, furthering the global advocacy for Romani rights."
    }
  ]
}

