    {
      "date": "1973-05-17",
      "headline": "Senate Watergate Committee Hearings",
      "text": "Televised hearings began, led by Senator Sam Ervin, investigating the Watergate scandal and uncovering significant evidence against the Nixon administration."
    },
    {
      "date": "1973-07-16",
      "headline": "Revelation of Tapes",
      "text": "Former White House aide Alexander Butterfield revealed the existence of a secret taping system in the Oval Office, which recorded conversations."
    },
    {
      "date": "1973-10-20",
      "headline": "Saturday Night Massacre",
      "text": "Nixon ordered the firing of special prosecutor Archibald Cox, leading to the resignations of Attorney General Elliot Richardson and Deputy Attorney General William Ruckelshaus."
