{
  "timeline": [
    {
      "date": "-0600",
      "headline": "Formation of Early Kingdoms",
      "text": "The early history of Nepal is characterized by the formation of small kingdoms and tribal confederations in the Kathmandu Valley and surrounding areas."
    },
    {
      "date": "0250",
      "headline": "Ashoka's Influence",
      "text": "Emperor Ashoka of the Maurya Empire visits Lumbini, the birthplace of Buddha, and erects a pillar marking the site."
    },
    {
      "date": "0320",
      "headline": "Licchavi Dynasty",
      "text": "The Licchavi dynasty begins its rule in the Kathmandu Valley, marking a period of cultural and political development."
    },
    {
      "date": "0600",
      "headline": "Thakuri Dynasty",
      "text": "The Thakuri dynasty rises to power after the decline of the Licchavi dynasty, continuing the development of the region."
    },
    {
      "date": "1200",
      "headline": "Malla Dynasty",
      "text": "The Malla dynasty begins, leading to a golden age of art, architecture, and culture in the Kathmandu Valley."
    },
    {
      "date": "1768",
      "headline": "Unification of Nepal",
      "text": "Prithvi Narayan Shah, the King of Gorkha, successfully unifies the small kingdoms into a single nation, establishing the Kingdom of Nepal."
    },
    {
      "date": "1814-1816",
      "headline": "Anglo-Nepalese War",
      "text": "The Anglo-Nepalese War occurs, resulting in the Sugauli Treaty, which cedes some Nepalese territory to the British East India Company."
    },
    {
      "date": "1846",
      "headline": "Rana Dynasty Begins",
      "text": "Jung Bahadur Rana seizes power, establishing the Rana dynasty, which rules Nepal as hereditary prime ministers with the king as a figurehead."
    },
    {
      "date": "1951",
      "headline": "End of Rana Rule",
      "text": "The Rana regime is overthrown, and King Tribhuvan returns to power, marking the beginning of a democratic movement in Nepal."
    },
    {
      "date": "1990",
      "headline": "Constitutional Monarchy Established",
      "text": "A people's movement leads to the establishment of a constitutional monarchy with a multi-party democracy."
    },
    {
      "date": "2001-06-01",
      "headline": "Royal Massacre",
      "text": "Crown Prince Dipendra kills several members of the royal family, including King Birendra, before dying by suicide."
    },
    {
      "date": "2006",
      "headline": "End of Civil War",
      "text": "A decade-long civil war between Maoist rebels and government forces ends with a peace agreement, leading to the abolition of the monarchy."
    },
    {
      "date": "2008-05-28",
      "headline": "Republic Declared",
      "text": "Nepal is declared a federal democratic republic, officially ending the monarchy and establishing a new political system."
    },
    {
      "date": "2015-04-25",
      "headline": "Gorkha Earthquake",
      "text": "A devastating earthquake strikes Nepal, causing widespread destruction and loss of life, and prompting international aid efforts."
    }
  ]
}

