    {
      "date": "1628-03-02",
      "headline": "Petition of Right",
      "text": "Charles I was compelled to accept the Petition of Right, a constitutional document that set out specific liberties of the subject that the king is prohibited from infringing."
    },
    {
      "date": "1629-03-10",
      "headline": "Dissolution of Parliament",
      "text": "Charles I dissolved Parliament and began his period of Personal Rule, which lasted for eleven years without calling a Parliament."
    },
    {
      "date": "1637",
      "headline": "Scottish Prayer Book Riots",
      "text": "The introduction of the Anglican Book of Common Prayer in Scotland led to widespread riots and resistance, contributing to the Bishops' Wars."
    },
    {
      "date": "1640-04-13",
      "headline": "Short Parliament",
      "text": "Charles I called the Short Parliament to raise funds for the Bishops' Wars, but it was dissolved after only three weeks."
    },
    {
      "date": "1640-11-03",
      "headline": "Long Parliament",
      "text": "The Long Parliament was convened, which would eventually lead to the English Civil War."
    },
    {
      "date": "1642-08-22",
      "headline": "Start of the English Civil War",
      "text": "Charles I raised his standard at Nottingham, marking the beginning of the English Civil War between the Royalists and Parliamentarians."
    },
    {
      "date": "1646-05-05",
      "headline": "Surrender to the Scots",
      "text": "Charles I surrendered to a Scottish army at Southwell, effectively ending his active role in the Civil War."
    },
    {
      "date": "1647-06-04",
      "headline": "Imprisonment by the New Model Army",
      "text": "Charles I was seized by the New Model Army and held captive, leading to negotiations and further conflict."
    },
    {
      "date": "1648-12-06",
      "headline": "Pride's Purge",
      "text": "The New Model Army purged the Long Parliament of members not supportive of the army's goals, leading to the Rump Parliament."
    },
    {
      "date": "1649-01-30",
      "headline": "Execution of Charles I",
      "text": "Charles I was executed outside the Banqueting House in Whitehall, London, after being found guilty of high treason by the Rump Parliament."
