{
  "timeline": [
    {
      "date": "1412",
      "headline": "Birth of Joan of Arc",
      "text": "Joan of Arc was born in Domrémy, a village in the duchy of Bar, in what is now eastern France. Her exact birth date is unknown, but she was born to Jacques d'Arc and Isabelle Romée."
    },
    {
      "date": "1425",
      "headline": "Joan Begins Hearing Voices",
      "text": "At the age of 13, Joan began hearing voices, which she identified as those of Saint Michael, Saint Catherine, and Saint Margaret. These voices instructed her to support Charles VII and help him reclaim his kingdom from English domination."
    },
    {
      "date": "1429-02",
      "headline": "Joan Meets Charles VII",
      "text": "Joan traveled to Chinon to meet Charles VII, the uncrowned King of France. She convinced him of her divine mission to drive the English out of France and to have him crowned at Reims."
    },
    {
      "date": "1429-04-29",
      "headline": "Siege of Orléans",
      "text": "Joan of Arc arrived at the besieged city of Orléans. Her presence and leadership were pivotal in lifting the siege, marking a turning point in the Hundred Years' War."
    },
    {
      "date": "1429-07-17",
      "headline": "Coronation of Charles VII",
      "text": "Joan of Arc played a crucial role in the coronation of Charles VII at Reims Cathedral, fulfilling one of her divine missions."
    },
    {
      "date": "1430-05-23",
      "headline": "Capture by the Burgundians",
      "text": "Joan was captured by Burgundian forces, allies of the English, during a military campaign at Compiègne."
    },
    {
      "date": "1431-01",
      "headline": "Trial of Joan of Arc",
      "text": "Joan was put on trial for charges including heresy, witchcraft, and cross-dressing. The trial was politically motivated and conducted by pro-English clergy."
    },
    {
      "date": "1431-05-30",
      "headline": "Execution of Joan of Arc",
      "text": "Joan of Arc was executed by burning at the stake in Rouen, which was then under English control. She was 19 years old."
    },
    {
      "date": "1456",
      "headline": "Posthumous Retrial and Rehabilitation",
      "text": "A posthumous retrial, authorized by Pope Callixtus III, nullified the original trial's verdict, declaring Joan innocent and a martyr."
    },
    {
      "date": "1920",
      "headline": "Canonization of Joan of Arc",
      "text": "Joan of Arc was canonized as a saint by the Roman Catholic Church, recognizing her as a martyr and a symbol of French unity and nationalism."
    }
  ]
}

