{
  "timeline": [
    {
      "date": "1789-09-24",
      "headline": "Establishment of the Supreme Court",
      "text": "The Supreme Court of the United States was established by the Judiciary Act of 1789, signed into law by President George Washington. The Act created a six-member Supreme Court and established the federal judiciary of the United States."
    },
    {
      "date": "1790-02-02",
      "headline": "First Session of the Supreme Court",
      "text": "The Supreme Court held its first session in New York City, which was then the capital of the United States. The Court initially had little business and struggled to find its role in the new government."
    },
    {
      "date": "1801-02-04",
      "headline": "John Marshall Becomes Chief Justice",
      "text": "John Marshall was appointed as the fourth Chief Justice of the United States by President John Adams. Marshall's tenure would significantly shape the role and power of the Supreme Court."
    },
    {
      "date": "1803",
      "headline": "Marbury v. Madison",
      "text": "In the landmark case Marbury v. Madison, the Supreme Court, under Chief Justice John Marshall, established the principle of judicial review, asserting the Court's power to strike down laws that violate the Constitution."
    },
    {
      "date": "1857",
      "headline": "Dred Scott v. Sandford",
      "text": "The Supreme Court ruled in Dred Scott v. Sandford that African Americans, whether enslaved or free, could not be American citizens and that Congress had no authority to prohibit slavery in federal territories."
    },
    {
      "date": "1896",
      "headline": "Plessy v. Ferguson",
      "text": "The Supreme Court upheld the constitutionality of racial segregation under the 'separate but equal' doctrine in the case of Plessy v. Ferguson."
    },
    {
      "date": "1954",
      "headline": "Brown v. Board of Education",
      "text": "In a landmark decision, the Supreme Court ruled in Brown v. Board of Education that racial segregation in public schools was unconstitutional, overturning Plessy v. Ferguson."
    },
    {
      "date": "1966",
      "headline": "Miranda v. Arizona",
      "text": "The Supreme Court ruled in Miranda v. Arizona that detained criminal suspects must be informed of their rights to an attorney and against self-incrimination prior to police questioning, leading to the creation of the 'Miranda rights.'"
    },
    {
      "date": "1973",
      "headline": "Roe v. Wade",
      "text": "The Supreme Court ruled in Roe v. Wade that the Constitution protects a woman's right to choose to have an abortion without excessive government restriction, effectively legalizing abortion nationwide."
    },
    {
      "date": "2000",
      "headline": "Bush v. Gore",
      "text": "The Supreme Court's decision in Bush v. Gore effectively resolved the 2000 presidential election in favor of George W. Bush by halting the Florida recount."
    },
    {
      "date": "2015",
      "headline": "Obergefell v. Hodges",
      "text": "The Supreme Court ruled in Obergefell v. Hodges that same-sex marriage is a constitutional right under the Fourteenth Amendment, legalizing it across the United States."
    }
  ]
}

