{
  "timeline": [
    {
      "date": "-1000",
      "headline": "Early Kingdoms",
      "text": "The region that is now Ethiopia was home to early kingdoms such as D'mt, which existed around the 10th century BCE. This kingdom is considered one of the earliest known civilizations in the area."
    },
    {
      "date": "-0800",
      "headline": "Rise of the Kingdom of Aksum",
      "text": "The Kingdom of Aksum emerged as a major trading empire in the region, known for its monumental obelisks and as a center of early Christianity in Africa."
    },
    {
      "date": "0330",
      "headline": "Christianity Adopted",
      "text": "Christianity was adopted as the state religion of the Kingdom of Aksum, making it one of the first regions in the world to officially embrace the faith."
    },
    {
      "date": "1137",
      "headline": "Zagwe Dynasty",
      "text": "The Zagwe dynasty came to power, known for its rock-hewn churches in Lalibela, which remain a significant cultural and religious site in Ethiopia."
    },
    {
      "date": "1270",
      "headline": "Solomonic Dynasty",
      "text": "The Solomonic dynasty was established, claiming descent from the biblical King Solomon and the Queen of Sheba. This dynasty ruled Ethiopia for several centuries."
    },
    {
      "date": "1529",
      "headline": "Ahmad ibn Ibrahim al-Ghazi's Campaigns",
      "text": "Ahmad ibn Ibrahim al-Ghazi, also known as Ahmad Gran, led a series of military campaigns against the Ethiopian Empire, significantly impacting the region."
    },
    {
      "date": "1855",
      "headline": "Reign of Emperor Tewodros II",
      "text": "Tewodros II became Emperor of Ethiopia, initiating efforts to modernize and unify the country, though his reign ended in conflict with British forces."
    },
    {
      "date": "1896-03-01",
      "headline": "Battle of Adwa",
      "text": "Ethiopian forces, under Emperor Menelik II, defeated the Italian army at the Battle of Adwa, securing Ethiopian sovereignty and becoming a symbol of anti-colonial resistance."
    },
    {
      "date": "1930-11-02",
      "headline": "Coronation of Haile Selassie I",
      "text": "Haile Selassie I was crowned Emperor of Ethiopia, later becoming a prominent figure in African unity and the Rastafari movement."
    },
    {
      "date": "1936",
      "headline": "Italian Occupation",
      "text": "Italy invaded and occupied Ethiopia, integrating it into Italian East Africa until Ethiopian and Allied forces liberated the country in 1941."
    },
    {
      "date": "1974",
      "headline": "Overthrow of Haile Selassie",
      "text": "Haile Selassie was deposed in a coup by the Derg, a Marxist-Leninist military junta, marking the end of the Ethiopian monarchy."
    },
    {
      "date": "1991",
      "headline": "End of the Derg Regime",
      "text": "The Ethiopian People's Revolutionary Democratic Front (EPRDF) overthrew the Derg regime, leading to the establishment of the Federal Democratic Republic of Ethiopia."
    },
    {
      "date": "1995",
      "headline": "New Constitution",
      "text": "Ethiopia adopted a new constitution, establishing a federal system of government and recognizing ethnic autonomy within the country."
    },
    {
      "date": "2018",
      "headline": "Abiy Ahmed Becomes Prime Minister",
      "text": "Abiy Ahmed became Prime Minister of Ethiopia, initiating political reforms and winning the Nobel Peace Prize in 2019 for his efforts to resolve the border conflict with Eritrea."
    }
  ]
}

