      "date": "-03000",
      "headline": "Earliest Known Use",
      "text": "The swastika symbol is found in archaeological sites dating back to the Neolithic period, around 3000 BCE, in the Indus Valley Civilization and other ancient cultures."
    },
    {
      "date": "-02000",
      "headline": "Use in Ancient Indian Religions",
      "text": "The swastika becomes a prominent symbol in Indian religions such as Hinduism, Buddhism, and Jainism, representing divinity, spirituality, and auspiciousness."
    },
    {
      "date": "-0500",
      "headline": "Spread to Ancient Greece",
      "text": "The swastika appears in ancient Greek art and architecture, often associated with the goddess Athena and used as a decorative motif."
    },
    {
      "date": "0200",
      "headline": "Use in Early Christianity",
      "text": "The swastika is used in early Christian art and architecture, sometimes referred to as the 'gammadion cross,' symbolizing eternity or Christ."
    },
    {
      "date": "1900",
      "headline": "Adoption by Western Occultists",
      "text": "The swastika is adopted by Western occultists and esoteric groups, including the Theosophical Society, as a symbol of good fortune and spiritual power."
    },
    {
      "date": "1920",
      "headline": "Adoption by the Nazi Party",
      "text": "The Nazi Party in Germany adopts the swastika as its official emblem, associating it with Aryan identity and German nationalism."
    },
    {
      "date": "1945",
      "headline": "End of World War II",
      "text": "Following the defeat of Nazi Germany, the swastika becomes widely associated with the atrocities of the Holocaust and is banned in several countries."
    },
    {
      "date": "2000",
      "headline": "Continued Use in Indian Religions",
      "text": "Despite its negative connotations in the West, the swastika continues to be used in Hinduism, Buddhism, and Jainism as a symbol of peace and prosperity."
    }
  ]
}

