{
  "timeline": [
    {
      "date": "1775-04-19",
      "headline": "Battles of Lexington and Concord",
      "text": "The first military engagements of the American Revolutionary War were fought in Middlesex County, Province of Massachusetts Bay, marking the outbreak of armed conflict between the Kingdom of Great Britain and its thirteen colonies in America."
    },
    {
      "date": "1775-06-17",
      "headline": "Battle of Bunker Hill",
      "text": "The British defeated the American forces at the Battle of Bunker Hill in Massachusetts. Despite their loss, the inexperienced colonial forces inflicted significant casualties against the enemy, providing them with an important confidence boost."
    },
    {
      "date": "1776-07-04",
      "headline": "Declaration of Independence",
      "text": "The Continental Congress adopted the Declaration of Independence, announcing that the thirteen American colonies regarded themselves as thirteen independent sovereign states, no longer under British rule."
    },
    {
      "date": "1776-12-26",
      "headline": "Battle of Trenton",
      "text": "General George Washington's army crossed the icy Delaware River and won a significant victory against Hessian forces at Trenton, New Jersey, boosting the Continental Army's morale."
    },
    {
      "date": "1777-10-17",
      "headline": "Surrender at Saratoga",
      "text": "British General John Burgoyne surrendered his army to American General Horatio Gates at Saratoga, New York. This American victory was a turning point in the war, convincing France to enter the war as an ally of the United States."
    },
    {
      "date": "1778-02-06",
      "headline": "Treaty of Alliance with France",
      "text": "The United States and France signed the Treaty of Alliance, formalizing French military support for the American cause, which was crucial for the eventual American victory."
    },
    {
      "date": "1781-10-19",
      "headline": "Surrender at Yorktown",
      "text": "British General Lord Cornwallis surrendered to American and French forces at Yorktown, Virginia, effectively ending major military operations in the American Revolutionary War."
    },
    {
      "date": "1783-09-03",
      "headline": "Treaty of Paris Signed",
      "text": "The Treaty of Paris was signed, officially ending the American Revolutionary War. Great Britain recognized the independence of the United States, and the boundaries of the new nation were established."
    }
  ]
}

