{
  "timeline": [
    {
      "date": "1999-12-24",
      "headline": "Hijacking of Flight 814",
      "text": "Indian Airlines Flight 814 was hijacked by five members of the militant group Harkat-ul-Mujahideen shortly after entering Indian airspace at approximately 16:53 IST. The flight was en route from Tribhuvan International Airport in Kathmandu, Nepal, to Indira Gandhi International Airport in Delhi, India."
    },
    {
      "date": "1999-12-24",
      "headline": "Landing in Amritsar",
      "text": "The hijacked aircraft made an emergency landing at Raja Sansi Airport in Amritsar, India, but took off again after a brief stop due to lack of refueling and negotiations."
    },
    {
      "date": "1999-12-24",
      "headline": "Landing in Lahore",
      "text": "The aircraft landed at Lahore Airport in Pakistan for refueling. Pakistani authorities allowed the plane to refuel and it departed after a few hours."
    },
    {
      "date": "1999-12-24",
      "headline": "Landing in Dubai",
      "text": "The hijacked plane landed at Dubai International Airport in the United Arab Emirates. 27 passengers were released, including a critically injured passenger who was stabbed by the hijackers."
    },
    {
      "date": "1999-12-25",
      "headline": "Arrival in Kandahar",
      "text": "The aircraft finally landed at Kandahar Airport in Afghanistan, which was under Taliban control at the time. The Taliban acted as a mediator between the hijackers and Indian authorities."
    },
    {
      "date": "1999-12-31",
      "headline": "Release of Hostages",
      "text": "After negotiations, the Indian government agreed to release three militants in exchange for the hostages. The hostages were released and the hijackers were allowed to leave for Pakistan."
    }
  ]
}

