    },
    {
      "date": "1661",
      "headline": "Marriage Treaty",
      "text": "As part of the dowry of Catherine of Braganza, the islands were ceded to the British Crown when she married Charles II of England."
    },
    {
      "date": "1668",
      "headline": "Lease to the British East India Company",
      "text": "The British Crown leased the islands to the British East India Company for a nominal annual rent."
    },
    {
      "date": "1782",
      "headline": "Hornby Vellard Project",
      "text": "Governor William Hornby initiated the Hornby Vellard project to reclaim the land between the islands, which was completed in 1784."
    },
    {
      "date": "1853",
      "headline": "First Railway in India",
      "text": "The first passenger railway line in India was inaugurated between Bombay (Mumbai) and Thane."
    },
    {
      "date": "1864",
      "headline": "Bombay High Court Established",
      "text": "The Bombay High Court was established, becoming one of the oldest high courts in India."
    },
    {
      "date": "1869",
      "headline": "Opening of the Suez Canal",
      "text": "The opening of the Suez Canal significantly boosted Bombay's trade and economy."
    },
    {
      "date": "1896",
      "headline": "Plague Epidemic",
      "text": "A bubonic plague epidemic broke out in Bombay, leading to significant loss of life and migration."
    },
    {
      "date": "1947",
      "headline": "Independence of India",
      "text": "Bombay became part of the newly independent India following the end of British rule."
    },
    {
      "date": "1960",
      "headline": "Formation of Maharashtra",
      "text": "Bombay became the capital of the newly formed state of Maharashtra after the division of the Bombay State."
    },
    {
      "date": "1995",
      "headline": "Renaming to Mumbai",
      "text": "The city was officially renamed Mumbai from Bombay, reflecting the Marathi pronunciation and honoring the local goddess Mumbadevi."
    },
    {
      "date": "2008",
      "headline": "Mumbai Named Alpha World City",
      "text": "Mumbai was named an alpha world city, recognizing its importance in the global economic system."
    }
  ]
}

{
